  '/dashboard/settings': { title: 'Settings', sub: 'WAF enforcement mode — the kill switch', render: () => <Settings /> },
};

export function Dashboard({ path }) {
  const live = useLiveStream();
  const page = PAGES[path] || PAGES['/dashboard'];

