            {node.zone === 'blast' && (
              <>
                <dt>Hops from confirmed</dt>
                <dd>{node.hops}</dd>
              </>
            )}
            {entry &&
              Object.entries(entry)
                .filter(([, value]) => value !== null && value !== undefined && value !== '')
                .map(([key, value]) => (
                  <div key={key}>
                    <dt>{key}</dt>
                    <dd>{typeof value === 'object' ? JSON.stringify(value) : String(value)}</dd>
                  </div>
                ))}
          </dl>
        </>
      )}
    </div>
  )
}

