import { useEffect, useRef, useState } from 'react';

/**
 * Reveal — fades + de-blurs its children up as they scroll into view.
 *
 * Uses a passive, rAF-throttled scroll check that unsubscribes the moment the
 * element reveals — so it's a one-shot trigger, not continuous scroll-driven
 * work (no reflow thrash). Respects prefers-reduced-motion by showing instantly.
 */
export function Reveal({ children, delay = 0, as: Tag = 'div', className = '', ...rest }) {
  const ref = useRef(null);
  const [shown, setShown] = useState(false);

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      setShown(true);
      return;
    }

    let done = false;
    let raf = 0;

    const cleanup = () => {
      window.removeEventListener('scroll', onScroll);
      window.removeEventListener('resize', onScroll);
      cancelAnimationFrame(raf);
    };

    const check = () => {
      const r = el.getBoundingClientRect();
      if (r.top < window.innerHeight * 0.92 && r.bottom > 0) {
        done = true;
        setShown(true);
        cleanup();
      }
    };

    const onScroll = () => {
      if (done) return;
      cancelAnimationFrame(raf);
      raf = requestAnimationFrame(check);
    };

    window.addEventListener('scroll', onScroll, { passive: true });
    window.addEventListener('resize', onScroll, { passive: true });
    check(); // reveal anything already in view on mount

    return cleanup;
  }, []);

  return (
    <Tag
      ref={ref}
      className={`reveal ${shown ? 'in' : ''} ${className}`}
      style={{ transitionDelay: `${delay}ms` }}
      {...rest}
    >
      {children}
    </Tag>
  );
}

/* ── Dwarpal · Neo-Brutalist landing ─────────────────────────────────────────
   Yellow #ffe17c · charcoal #171e19 · sage #b7c6c2. 2px black borders, hard
   offset shadows (0 blur), Cabinet Grotesk + Satoshi, press-down buttons.
   Everything scoped under .brut so it never leaks into the glass dashboard. */

@import url('https://api.fontshare.com/v2/css?f[]=cabinet-grotesk@400,500,700,800&f[]=satoshi@400,500,700&display=swap');

.brut {
  --yellow: #ffe17c;
  --charcoal: #171e19;
  --sage: #b7c6c2;
  --ink: #000000;
  --paper: #ffffff;
  --gray: #272727;

  --display: 'Cabinet Grotesk', system-ui, sans-serif;
  --body: 'Satoshi', system-ui, sans-serif;

  --sh: 4px 4px 0 0 var(--ink);
  --sh-lg: 8px 8px 0 0 var(--ink);
  --sh-xl: 12px 12px 0 0 var(--ink);
  --press: cubic-bezier(0.175, 0.885, 0.32, 1.275);

  font-family: var(--body);
  font-weight: 500;
  color: var(--ink);
  background: var(--yellow);
  overflow-x: hidden;
}

.brut h1, .brut h2, .brut h3, .brut h4 {
  font-family: var(--display);
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 0.98;
}
.brut a { color: inherit; text-decoration: none; }
.brut ::selection { background: var(--ink); color: var(--yellow); }

.wrap { max-width: 1200px; margin: 0 auto; padding: 0 28px; }

/* dot texture for yellow sections */
.dots {
  background-image: radial-gradient(circle, rgba(0, 0, 0, 0.1) 1.5px, transparent 1.5px);
  background-size: 32px 32px;
}

/* ── Buttons (press-down) ────────────────────────────────────────────────── */
.btn {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-family: var(--body);
  font-weight: 700;
  font-size: 15px;
  padding: 13px 22px;
  border: 2px solid var(--ink);
  border-radius: 12px;
  cursor: pointer;
  transition: transform 0.18s var(--press), box-shadow 0.18s var(--press), background 0.18s;
}
.btn-lg { box-shadow: var(--sh-lg); }
.btn-sm { box-shadow: var(--sh); }
.btn-lg:hover { transform: translate(4px, 4px); box-shadow: var(--sh); }
.btn-sm:hover { transform: translate(4px, 4px); box-shadow: 0 0 0 0 var(--ink); }
.btn:active { transform: translate(4px, 4px); box-shadow: 0 0 0 0 var(--ink); }

.btn-black { background: var(--ink); color: var(--paper); }
.btn-white { background: var(--paper); color: var(--ink); }
.btn-yellow { background: var(--yellow); color: var(--ink); }

.btn .arw {
  display: inline-flex;
  width: 20px;
  height: 20px;
  align-items: center;
  justify-content: center;
}

/* ── Nav ─────────────────────────────────────────────────────────────────── */
.bnav {
  position: sticky;
  top: 0;
  z-index: 50;
  height: 76px;
  background: var(--yellow);
  border-bottom: 2px solid var(--ink);
}
.bnav-in {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 28px;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  font-family: var(--display);
  font-weight: 800;
  font-size: 20px;
  letter-spacing: -0.02em;
}
.brand-mark {
  width: 38px;
  height: 38px;
  border: 2px solid var(--ink);
  border-radius: 9px;
  background: var(--ink);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-shadow: var(--sh);
}
.bnav-links {
  display: flex;
  gap: 30px;
  font-weight: 700;
  font-size: 15px;
}
.bnav-links a { position: relative; }
.bnav-links a:hover { text-decoration: underline; text-underline-offset: 4px; text-decoration-thickness: 2px; }

/* ── Generic section frame ───────────────────────────────────────────────── */
.sec { border-bottom: 2px solid var(--ink); }
.sec-pad { padding: 88px 0; }
.hbadge {
  display: inline-flex;
  width: fit-content;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 999px;
  font-weight: 700;
  font-size: 12px;
  letter-spacing: 0.06em;
