/* gatekeeper — solid word on a rotated highlighter swipe */
.hero .stroke {
  position: relative;
  display: inline-block;
  color: var(--ink);
  z-index: 0;
}
.hero .stroke::before {
  content: '';
  position: absolute;
  left: -0.06em;
  right: -0.06em;
  top: 0.16em;
  bottom: 0.05em;
  background: var(--sage);
  transform: rotate(-2.2deg);
  z-index: -1;
}
.hero p {
  font-size: 18px;
